using Avalonia.Controls;
using Avalonia.Headless.XUnit;
using Avalonia.Media;
using ProDesigner.Authoring;
using ProDesigner.Core;
using ProDesigner.Design;
using ProDesigner.Preview;
using ProDesigner.Runtime;
using ProDesigner.Xaml;
using Xunit;

namespace ProDesigner.Tests;
public class AuthoringTests
{
    [Fact] public void UpdatingStyleRetainsItsAnimationsAndUnrelatedSetters()
    {
        var tree=XamlSyntaxTree.Parse("<UserControl><UserControl.Styles><Style Selector='Button.primary'><Setter Property='Opacity' Value='0.5'/><!-- retain --><Style.Animations/></Style></UserControl.Styles></UserControl>");
        var source=EditApplication.Apply(tree.Source,XamlAuthoring.UpsertStyle(tree,"Button.primary",new Dictionary<string,string>{{"Background","Purple"}}));
        Assert.Contains("Value='0.5'",source);Assert.Contains("<!-- retain -->",source);Assert.Contains("<Style.Animations/>",source);Assert.Contains("Background",source);
    }
    [Fact] public void ResourceUpdateDoesNotReplaceTheWholeDictionary()
    {
        var tree=XamlSyntaxTree.Parse("<UserControl xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'><UserControl.Resources><SolidColorBrush x:Key='Other' Color='Red'/><!-- keep --><SolidColorBrush x:Key='Accent' Color='Blue'/></UserControl.Resources></UserControl>");
        var source=EditApplication.Apply(tree.Source,XamlAuthoring.UpsertResource(tree,"Accent","SolidColorBrush",new Dictionary<string,string>{{"Color","Green"}}));
        Assert.Contains("x:Key='Other' Color='Red'",source);Assert.Contains("<!-- keep -->",source);Assert.Equal(1,XamlSyntaxTree.Parse(source).Elements.Count(n=>XamlAuthoring.Key(n)=="Accent"));
    }
    [AvaloniaFact] public void GradientAuthoringCreatesARealAvaloniaGradient()
    {
        var tree=XamlSyntaxTree.Parse("<Border xmlns='https://github.com/avaloniaui' Background='Blue'/>");
        var source=EditApplication.Apply(tree.Source,XamlAuthoring.SetPropertyObject(tree,tree.Root,"Background",new GradientModel(0,0,1,1,[new(0,"Red"),new(1,"Blue")]).ToXaml()));
        using var runtime=new RuntimePreviewEngine().Load(new(source,Trusted:true));
        Assert.IsType<LinearGradientBrush>(((Border)runtime.Root).Background);
        var safe=new PreviewBuilder().Build(XamlSyntaxTree.Parse(source),PreviewProfile.Defaults[0]);Assert.Empty(safe.Diagnostics);Assert.IsType<LinearGradientBrush>(((Border)safe.Controls["0"]).Background);
    }
    [AvaloniaFact] public void AuthoredControlThemeLoadsInAvalonia()
    {
        var tree=XamlSyntaxTree.Parse("<UserControl xmlns='https://github.com/avaloniaui'><Button Theme='{StaticResource Primary}'/></UserControl>");
        var source=EditApplication.Apply(tree.Source,XamlAuthoring.UpsertTheme(tree,"Primary","Button",new Dictionary<string,string>{{"Background","Purple"},{"CornerRadius","8"}}));
        using var preview=new RuntimePreviewEngine().Load(new(source,Trusted:true));Assert.IsType<UserControl>(preview.Root);
    }
    [Theory] [InlineData("M0,0 L10,20 Z")] [InlineData("M0,0 c10,20 30,40 50,60 q10,20 30,40 z")] [InlineData("m10,20 30,40 50,60")]
    public void VectorGeometryRoundTripsSupportedCommands(string source)
    { var path=VectorPathModel.Parse(source);Assert.Equal(path.ToData(),VectorPathModel.Parse(path.ToData()).ToData()); }
    [Fact] public void VectorPointEditingChangesOnlyItsSegment()
    { var path=VectorPathModel.Parse("M0,0 C10,20 30,40 50,60");path.SetPoint(1,0,new(15,25));Assert.Equal("M 0,0 C 15,25 30,40 50,60",path.ToData()); }
    [Fact] public void UnknownPathCommandsAreNeverSilentlyDiscarded() => Assert.Throws<FormatException>(()=>VectorPathModel.Parse("M0,0 A10,10 0 0 1 20,20"));
    [Fact] public void InvalidGradientIsRejected() => Assert.Throws<ArgumentException>(()=>new GradientModel(0,0,1,1,[new(-1,"Red"),new(1,"Blue")]).ToXaml());
}

using Avalonia.Controls;
using Avalonia.Headless.XUnit;
using ProDesigner.Animation;
using ProDesigner.Persistence;
using ProDesigner.Workbench;
using Xunit;

namespace ProDesigner.Tests;
public class AuthoringWorkbenchTests
{
    [AvaloniaFact] public void WorkspaceRoundTripRestoresTabsSourceCodeAndTimeline()
    {
        using var workbench=new DesignerWorkbench();workbench.SelectByName("RevenueCard");workbench.SetProperty("Width","280");workbench.Documents[0].CodeBehind="class Draft {}";
        var json=workbench.ExportWorkspace();workbench.Execute("new");workbench.ImportWorkspace(json);
        Assert.Equal(3,workbench.Documents.Count);Assert.Equal("280",workbench.Session.Primary!.Get("Width"));Assert.Equal("class Draft {}",workbench.Documents[0].CodeBehind);Assert.Single(workbench.Documents[0].Animation.Tracks);
    }
    [AvaloniaFact] public void AuthoringToolsAndVectorEditorCanBeOpened()
    {
        using var workbench=new DesignerWorkbench();var window=new Window{Width=1600,Height=1000,Content=workbench};window.Show();
        workbench.Execute("authoring");workbench.Execute("new");workbench.InsertControl("Path");workbench.Execute("vector");Assert.Contains("<Path",workbench.Session.Source);window.Close();
    }
    [AvaloniaFact] public void NewControlInsertionWorksWithoutAnExistingXPrefix()
    {
        using var workbench=new DesignerWorkbench();workbench.OpenDocument("View.axaml","<UserControl xmlns='https://github.com/avaloniaui'><Canvas/></UserControl>");workbench.InsertControl("Button");Assert.True(workbench.Session.IsValid);Assert.Contains("Button1",workbench.Session.Source);
    }
    [AvaloniaFact] public void ClipboardPasteKeepsInternalBindingReferencesValid()
    {
        using var workbench=new DesignerWorkbench();workbench.OpenDocument("View.axaml","<UserControl xmlns='https://github.com/avaloniaui' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'><Canvas><StackPanel x:Name='Group'><TextBox x:Name='Input'/><TextBlock Text='{Binding ElementName=Input}'/></StackPanel></Canvas></UserControl>");
        workbench.SelectByName("Group");workbench.Execute("copy");workbench.SelectByName("Canvas");workbench.Execute("paste");
        Assert.Contains("ElementName=InputCopy",workbench.Session.Source);Assert.True(workbench.Session.IsValid);
    }
}

using ProDesigner.Animation;
using ProDesigner.Core;
using ProDesigner.Persistence;
using Xunit;

namespace ProDesigner.Tests;
public class PersistenceTests
{
    private static WorkspaceState State(string source="<Grid/>") => new(1,"Test",0,1,[PreviewProfile.Defaults[0]],[new("View.axaml",source,"<Grid/>","class View {}",null,null,ClipState.Capture(new AnimationClip()),[])]);
    [Fact] public void WorkspaceRestoresInvalidIntermediateSourceExactly()
    {var json=WorkspaceCodec.Serialize(State("<Grid>broken"));Assert.Equal("<Grid>broken",WorkspaceCodec.Deserialize(json).Documents[0].Source);}
    [Fact] public void CorruptPayloadIsRejected() => Assert.Throws<InvalidDataException>(()=>WorkspaceCodec.Deserialize(WorkspaceCodec.Serialize(State()).Replace("Test","Tampered",StringComparison.Ordinal)));
    [Fact] public void FutureSchemaIsNotSilentlyDowngraded() => Assert.Throws<InvalidDataException>(()=>WorkspaceCodec.Serialize(State() with {SchemaVersion=100}));
    [Fact] public void InvalidPreviewDimensionsAreRejected() => Assert.Throws<InvalidDataException>(()=>WorkspaceCodec.Serialize(State() with {Profiles=[new("Bad",double.NaN,100)]}));
    [Fact] public void AnimationPersistenceRetainsSplinesAndColors()
    {
        var clip=new AnimationClip();clip.GetTrack("Card","Opacity").SetKey(.4,.8,EasingKind.Custom,new(.2,0,.8,1));clip.GetColorTrack("Card","Background").SetKey(.6,ColorValue.Parse("#80402010"));
        var state=State();state=state with {Documents=[state.Documents[0] with {Animation=ClipState.Capture(clip)}]};
        var restored=WorkspaceCodec.Deserialize(WorkspaceCodec.Serialize(state)).Documents[0].Animation.Restore();Assert.Equal(clip.Tracks[0].Keys[0],restored.Tracks[0].Keys[0]);Assert.Equal(clip.ColorTracks[0].Keys[0],restored.ColorTracks[0].Keys[0]);
    }
    [Fact] public async Task AtomicSaveDetectsExternalChanges()
    {
        var folder=Path.Combine(Path.GetTempPath(),"prodesigner-atomic-"+Guid.NewGuid());Directory.CreateDirectory(folder);
        try
        {
            var path=Path.Combine(folder,"View.axaml");var token=TestContext.Current.CancellationToken;
            var hash=await AtomicFileStore.WriteAsync(path,"before",null,token);await File.WriteAllTextAsync(path,"external",token);
            await Assert.ThrowsAsync<FileConflictException>(()=>AtomicFileStore.WriteAsync(path,"lost-update",hash,token));Assert.Equal("external",await File.ReadAllTextAsync(path,token));
        }finally{Directory.Delete(folder,true);}
    }
    [Fact] public async Task RecoveryFallsBackToVerifiedPreviousGeneration()
    {
        var folder=Path.Combine(Path.GetTempPath(),"prodesigner-recovery-"+Guid.NewGuid());Directory.CreateDirectory(folder);
        try
        {
            var path=Path.Combine(folder,"recovery");var store=new FileRecoveryStore(path);var token=TestContext.Current.CancellationToken;
            var before=WorkspaceCodec.Serialize(State("<Grid/>"));await store.WriteAsync(before,token);await store.WriteAsync(WorkspaceCodec.Serialize(State("<Canvas/>")),token);
            await File.WriteAllTextAsync(path,"partial corrupt bytes",token);Assert.Equal(before,await store.ReadAsync(token));
        }finally{Directory.Delete(folder,true);}
    }
}

using System.Buffers.Binary;
using ProDesigner.Core;
using ProDesigner.PreviewProtocol;
using Xunit;

namespace ProDesigner.Tests;
public class PreviewProcessTests
{
    private static string Worker()
    {
        var root=new DirectoryInfo(AppContext.BaseDirectory);while(root is not null&&!File.Exists(Path.Combine(root.FullName,"ProDesigner.slnx")))root=root.Parent;
        if(root is null)throw new DirectoryNotFoundException("Cannot locate repository root.");
        var configuration=AppContext.BaseDirectory.Contains(Path.DirectorySeparatorChar+"Release"+Path.DirectorySeparatorChar)?"Release":"Debug";
        return Path.Combine(root.FullName,"apps","ProDesigner.Desktop","bin",configuration,"net10.0","ProDesigner.Desktop.dll");
    }
    [Fact] public async Task WireRoundTripsAndRejectsOversizedFrames()
    {
        using var stream=new MemoryStream();var token=TestContext.Current.CancellationToken;
        await PreviewWire.WriteAsync(stream,[1,2,3],token);stream.Position=0;Assert.Equal(new byte[]{1,2,3},await PreviewWire.ReadAsync(stream,token));
        stream.SetLength(0);var header=new byte[4];BinaryPrimitives.WriteInt32LittleEndian(header,int.MaxValue);await stream.WriteAsync(header,token);stream.Position=0;
        await Assert.ThrowsAsync<InvalidDataException>(()=>PreviewWire.ReadAsync(stream,token));
    }
    [Fact] public async Task IsolatedWorkerRendersUpdatesAndSurvivesMalformedXaml()
    {
        var token=TestContext.Current.CancellationToken;
        await using var worker=await PreviewProcessClient.StartAsync(Worker(),headless:true,cancellationToken:token);
        Assert.NotEqual(Environment.ProcessId,worker.ProcessId);
        var response=await worker.UpdateAsync(new("<Border xmlns='https://github.com/avaloniaui'><Button Content='Preview'/></Border>",Trusted:true),cancellationToken:token);Assert.True(response.Success,response.Error);Assert.True(response.ControlCount>=2);
        var failed=await worker.UpdateAsync(new("<Grid>",Trusted:true),cancellationToken:token);Assert.False(failed.Success);
        Assert.True((await worker.PingAsync(token)).Success);Assert.True(worker.IsAlive);
    }
    [Fact] public async Task KillingWorkerDoesNotKillDesignerAndDisconnectIsObserved()
    {
        var token=TestContext.Current.CancellationToken;await using var worker=await PreviewProcessClient.StartAsync(Worker(),true,token);
        using(var child=System.Diagnostics.Process.GetProcessById(worker.ProcessId)){child.Kill(entireProcessTree:true);await child.WaitForExitAsync(token);}
        await Assert.ThrowsAnyAsync<Exception>(()=>worker.PingAsync(token));Assert.True(Environment.ProcessId>0);
    }
    [Fact] public async Task UntrustedRequestNeverReachesTheWorker()
    {
        var token=TestContext.Current.CancellationToken;await using var worker=await PreviewProcessClient.StartAsync(Worker(),true,token);
        await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>worker.UpdateAsync(new("<Grid/>"),cancellationToken:token));Assert.True((await worker.PingAsync(token)).Success);
    }
}
